RD = {x['id']: x for x in json.load(open('src/data/readings.json', encoding='utf-8'))}


def game_step(gid, how, after):
    g = G[gid]
    return f"״{g['name']}״ (משחק מוכר, בלי קישור לנושא).\n\n{g['description']}\n\n{how}\n\nאחרי המשחק שואלים: {after}"


def make(a):
    t = a['times']
    r = RD[a['reading']]
    gstep = game_step(a['game'], a['game_how'], a['game_after'])
    flow = [
        {'label': f'פתיחה ({t[0]} דק׳)', 'body': a['opening']},
        {'label': f'משחק ({t[1]} דק׳)', 'body': gstep},
        {'label': f'מתודה ({t[2]} דק׳)', 'body': a['method']},
        {'label': f'קטע קריאה ({t[3]} דק׳)', 'body': f"קוראים בקול:\n\n״{r['title']}״\n\n{r['text']}"},
        {'label': f'דיון ({t[4]} דק׳)', 'items': a['discussion']},
        {'label': f'הסבר ({t[5]} דק׳)', 'body': a['explain']},
        {'label': f'סיכום ({t[6]} דק׳)', 'body': a['summary']},
    ]
    return dict(id=a['id'], title=a['title'], categorySlug='activities', subtopics=a['subtopics'], ageLabel=age_label(a['ageMin'], a['ageMax']),
        ageMin=a['ageMin'], ageMax=a['ageMax'], duration=sum(t), groupSize='8–25 חניכים', equipment=[], shabbat='שניהם',
        place='פנים', energy=a['energy'], depth=a['depth'], values=a['values'], tags=a['tags'], rating=4.6, character='C', description=a['description'],
        goals=a['goals'], opening=a['opening'], game=gstep, method=a['method'], discussion=a['discussion'],
        guideNotes=a.get('guide', ''), summary=a['summary'], tip=a['tip'], shabbatNote='כולה בעל פה ובלי ציוד, מתאימה לשבת.', flow=flow)


